using WypozyczalniaSportowa.Domain.Exceptions;
namespace WypozyczalniaSportowa.Domain; public sealed class ServiceOrder : Entity { private string _description = ""; public ServiceOrder(int equipmentId, string description) { EquipmentId = equipmentId; Description = description; } internal ServiceOrder(int id, int equipmentId, string description, bool completed) : base(id) { EquipmentId = equipmentId; Description = description; IsCompleted = completed; } public int EquipmentId { get; } public string Description { get => _description; private set => _description = string.IsNullOrWhiteSpace(value) ? throw new DomainValidationException("Opis przeglądu jest wymagany.") : value.Trim(); } public DateTime CreatedAt { get; } = DateTime.Now; public bool IsCompleted { get; private set; } public void Complete() { if (IsCompleted) throw new DomainValidationException("Serwis zakończono wcześniej."); IsCompleted = true; } public override Entity Clone(bool deep) => new ServiceOrder(Id, EquipmentId, Description, IsCompleted); public override string ToString() => $"Serwis #{Id} sprzętu #{EquipmentId}: {Description} ({(IsCompleted ? "gotowy" : "oczekuje")})"; }
